typedef struct { int data[100]; int top; } Stack;
void init(Stack *s) { s->top = -1; }
int push(Stack *s, int x) { if (s->top == 99) return -1; s->data[++s->top] = x; return 0; }
int pop(Stack *s, int *out) { if (s->top < 0) return -1; *out = s->data[s->top--]; return 0; }

